    "final_answer": "Total linear momentum in an isolated system is conserved.",
    "verify_code": "import sympy as sp\np_before = 0.45 * 9\np_after = p_before\nprint(f\"Total linear momentum in an isolated system is conserved. p_before = p_after = {p_before} kg·m/s\")",
    "techniques": ["verbal_principle", "mark_allocation"]
  }
